const fs=require('node:fs'),path=require('node:path');
const {JSDOM,VirtualConsole}=require('jsdom');
let w;
const start=new Date(2026,0,5,12).getTime(),day=86400000,now=start+21*day;
function event(id,at,ended=true,habitId='h-read'){return {id,name:'阅读一节教程',habitId,startedAt:at,endedAt:ended?at:null,segments:[{start:at,end:at}],steps:[],stepDone:{},repeatText:'',draft:'',notes:[]}}
function history(counts=[5,5,5,4]){return counts.flatMap((count,week)=>Array.from({length:count},(_,i)=>event('week-'+week+'-'+i,start+week*7*day+i)))}
function mount(events,focus='h-wake'){const html=fs.readFileSync(path.join(__dirname,'../index.html'),'utf8');w=new JSDOM(html,{url:'http://localhost/',runScripts:'outside-only',virtualConsole:new VirtualConsole()}).window;w.Date.now=()=>now+100;w.HTMLElement.prototype.checkVisibility=function(){return !this.hidden};w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false;this.dispatchEvent(new w.Event('close'))};w.eval(html.match(/<script>([\s\S]*?)<\/script>/)[1]+'\nwindow.install=(events,focus)=>{S=seed();S.user={id:"habit-test",name:"习惯验收",example:true};S.events=events;S.habitId=focus;validateSavedState(S);normalize();render();};');w.install(events,focus)}
function click(action){const b=w.document.querySelector(`[data-action="${action}"]`);if(!b)throw Error('Missing '+action);b.click()}
afterEach(()=>w?.close());
it('forms the completed event habit after focus was switched without changing the new focus',()=>{mount([...history(),event('last',now+5,false)],'h-read');click('resume:last');click('nav:habits');click('switch-habit:h-wake');expect(w.dianliangState.activeId).toBe('last');click('nav:timer');const before=w.dianliangState.events.length,finishButton=w.document.querySelector('[data-action="finish:last"]');click('finish:last');expect(w.dianliangState.habits.find(h=>h.id==='h-read').formedAt).toBe(now+100);expect(w.dianliangState.habits.find(h=>h.id==='h-wake').formedAt).toBeNull();expect(w.dianliangState.habitId).toBe('h-wake');click('dialog-close');expect(w.document.querySelector('[data-action="finish:last"]')).toBeNull();finishButton.click();expect(w.dianliangState.events.length).toBe(before)});
it('counts distinct completions rather than requiring five distinct days',()=>{mount([...history(),event('last',now+5,false)],'h-read');click('finish:last');expect(w.dianliangState.habits.find(h=>h.id==='h-read').formedAt).not.toBeNull()});
it('does not form from a missing week, another habit, future completions or unfinished events',()=>{const events=history([5,4,5,4]);events.push(event('other',start+7*day+10,true,'h-wake'),event('future',now+8*day),event('pending',start+7*day+20,false),event('last',now+5,false));mount(events);click('finish:last');expect(w.dianliangState.habits.find(h=>h.id==='h-read').formedAt).toBeNull()});
it('does not count pauses or repeated resumes as additional completed practices',()=>{mount([...history(),event('last',now+5,false)],'h-read');for(let i=0;i<4;i++){click('resume:last');click('pause')}expect(w.dianliangState.habits.find(h=>h.id==='h-read').formedAt).toBeNull();expect(w.dianliangState.events.filter(e=>e.habitId==='h-read'&&e.endedAt!==null)).toHaveLength(19);click('finish:last');expect(w.dianliangState.habits.find(h=>h.id==='h-read').formedAt).not.toBeNull()});
